       // use them directly without hitting the crypto exchange endpoint.
       if (initialCandles && initialCandles.length > 0 && targetSeries) {
         const data = initialCandles.map((c) => ({
           time: c.time as any,
           open: c.open,
           high: c.high,
           low: c.low,
           close: c.close,
         }));
