         targetSeries.setData(data);
         const allPrices = data.flatMap((c) => [c.open, c.high, c.low, c.close]).filter((p) => p > 0);
         if (allPrices.length > 0) {
           const precision = calcChartPrecision(allPrices);
           const minMove = calcMinMove(allPrices);
