/**
 * zonesOverlay — lightweight-charts Series Primitive that draws the desk's
 * zone read directly on the price pane:
 *   • supply/demand rectangles extending right from their creation bar
 *   • fib retracement bands (premium red / equilibrium green / discount blue)
 *   • trendline channel rails
 *
 * Everything is drawn in one canvas pass per frame via a bottom-z-order pane
 * view, so it never intercepts crosshair events and costs nothing when the
 * data is empty.
 */
import type {
  ISeriesApi,
  IChartApi,
  SeriesAttachedParameter,
  IUpdatableSeriesPrimitive,
  ISeriesPrimitivePaneView,
  IPrimitivePaneRenderer,
} from 'lightweight-charts';

export interface ZoneRect {
  type: 'supply' | 'demand';
  high: number;
  low: number;
  state: string;
  strength: number;
  createdTime: number; // ms epoch
}

export interface FibBand {
  ratio: number | null;
  price: number | null;
}

export interface FibPayload {
  swing?: { direction?: string | null; high?: number | null; low?: number | null } | null;
  bands: FibBand[];
}

export interface ChannelLine {
  kind: string;
  upperStart: number; // fitted price at window start
  upperNow: number;   // fitted price at last bar
  lowerStart: number;
  lowerNow: number;
  breakout?: string | null;
}

export interface ZonesData {
  supply_zones: ZoneRect[];
  demand_zones: ZoneRect[];
  channels?: ChannelLine[];
  s_r_levels?: { price: number; type: string; touches: number }[];
  fib?: FibPayload;
}

interface Rect { x0: number; x1: number; yTop: number; yBot: number }

const COLORS = {
  demandFill: 'rgba(34, 197, 94, 0.14)',
  demandEdge: 'rgba(34, 197, 94, 0.55)',
  supplyFill: 'rgba(239, 68, 68, 0.13)',
  supplyEdge: 'rgba(239, 68, 68, 0.5)',
  premium: 'rgba(239, 68, 68, 0.07)',
  equilibrium: 'rgba(34, 197, 94, 0.08)',
  discount: 'rgba(59, 130, 246, 0.09)',
  fibLine: 'rgba(148, 163, 184, 0.45)',
  goldenLine: 'rgba(250, 204, 21, 0.65)',
  channelUpper: 'rgba(96, 165, 250, 0.7)',
  channelLower: 'rgba(96, 165, 250, 0.7)',
};

class ZonesPaneRenderer implements IPrimitivePaneRenderer {
  constructor(private rects: Rect[]) {}

  draw(target: any) {
    target.useMediaCoordinateSpace((scope: any) => {
      const ctx = scope.context;
      for (const r of this.rects) {
        if (r.yTop === null || r.yBot === null) continue;
        ctx.fillStyle = r.color;
        ctx.fillRect(r.x0, Math.min(r.yTop, r.yBot), r.x1 - r.x0, Math.abs(r.yBot - r.yTop));
        if (r.edge) {
          ctx.strokeStyle = r.edge;
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(r.x0, r.yTop); ctx.lineTo(r.x1, r.yTop);
          ctx.moveTo(r.x0, r.yBot); ctx.lineTo(r.x1, r.yBot);
          ctx.stroke();
        }
      }
    });
  }
}

interface DrawRect extends Rect { color: string; edge?: string }

class ZonesPaneView implements ISeriesPrimitivePaneView {
  _rects: DrawRect[] = [];
  zOrder(): string { return 'bottom'; }
  renderer(): IPrimitivePaneRenderer {
    return new ZonesPaneRenderer(this._rects as Rect[]);
  }
}

export class ZonesOverlay implements IUpdatableSeriesPrimitive {
  private _view = new ZonesPaneView();
  private _data: ZonesData | null = null;
  private _params: SeriesAttachedParameter<any> | null = null;

  setData(data: ZonesData | null) {
    this._data = data;
    this._rebuild();
  }

  attached(params: SeriesAttachedParameter<any>) { this._params = params; }
  detached() { this._params = null; }

  updateAllViews() { this._rebuild(); }

  paneViews(): ISeriesPrimitivePaneView[] { return [this._view]; }

  private _rebuild() {
    const rects: DrawRect[] = [];
    const p = this._params;
    const data = this._data;
    if (!p || !data || !data.supply_zones && !data.demand_zones) {
      this._view._rects = rects;
      return;
    }
    const { chart, series } = p;
    const timeScale = chart.timeScale();
    const width = timeScale.width();
    const right = timeScale.scrollPosition();

    const yOf = (price: number): number | null => {
      const y = series.priceToCoordinate(price);
      return y ?? null;
    };
    // X for an ms-epoch timestamp; fall back to left edge when off-screen.
    const xOf = (ms: number): number => {
      const t = Math.floor(ms / 1000) as any;
      const x = timeScale.timeToCoordinate(t);
      return x ?? -10;
    };

    // ── Supply / Demand rectangles ─────────────────────────────
    for (const z of [...(data.demand_zones ?? []), ...(data.supply_zones ?? [])]) {
      const yTop = yOf(z.high);
      const yBot = yOf(z.low);
      if (yTop === null || yBot === null) continue;
      rects.push({
        x0: xOf(z.createdTime),
        x1: width,
        yTop, yBot,
        color: z.type === 'demand' ? COLORS.demandFill : COLORS.supplyFill,
        edge: z.type === 'demand' ? COLORS.demandEdge : COLORS.supplyEdge,
      });
    }

    // ── Fibonacci bands (premium / equilibrium / discount) ─────
    const fib = data.fib;
    if (fib?.bands?.length && fib.swing?.high != null && fib.swing?.low != null) {
      const sorted = [...fib.bands]
        .filter((b) => b.price != null)
        .sort((a, b) => (b.price! - a.price!));
      const priceOf = (ratio: number): number | null =>
        fib.bands.find((b) => Math.abs((b.ratio ?? -1) - ratio) < 1e-6)?.price ?? null;
      const hi = fib.swing.direction === 'down'
        ? (sorted[0]?.price ?? fib.swing.high)
        : (sorted[0]?.price ?? fib.swing.high);
      const top = sorted[0]?.price ?? null;
      const bot = sorted[sorted.length - 1]?.price ?? null;
      const p382 = priceOf(0.382);
      const p618 = priceOf(0.618);
      if (top != null && p382 != null) rects.push({ x0: 0, x1: width, yTop: yOf(top)!, yBot: yOf(p382)!, color: COLORS.premium });
      if (p382 != null && p618 != null) rects.push({ x0: 0, x1: width, yTop: yOf(p382)!, yBot: yOf(p618)!, color: COLORS.equilibrium });
      if (p618 != null && bot != null) rects.push({ x0: 0, x1: width, yTop: yOf(p618)!, yBot: yOf(bot)!, color: COLORS.discount });

      // Level lines — golden zone highlighted
      for (const b of sorted) {
        const y = yOf(b.price!);
        if (y === null) continue;
        const isGolden = b.ratio != null && b.ratio >= 0.38 && b.ratio <= 0.62;
        rects.push({ x0: 0, x1: width, yTop: y, yBot: y, color: 'transparent', edge: isGolden ? COLORS.goldenLine : COLORS.fibLine });
      }
    }

    // ── Channel rails ────────────────────────────────────────────
    for (const c of data.channels ?? []) {
      for (const pair of [[c.upperStart, c.upperNow], [c.lowerStart, c.lowerNow]] as const) {
        const yA = yOf(pair[0]);
        const yB = yOf(pair[1]);
        if (yA === null || yB === null) continue;
        // Rails span the fetched window: approximate from the left edge to
        // the right edge using both endpoint prices.
        rects.push({
          x0: 0,
          x1: width,
          yTop: yA,
          yBot: yB,
          color: 'transparent',
          edge: COLORS.channelUpper,
        });
      }
    }

    this._view._rects = rects;
  }
}

/** Attach the overlay to a candlestick series and get a handle for updates. */
export function attachZonesOverlay(
  series: ISeriesApi<'Candlestick'>,
  chart: IChartApi,
): ZonesOverlay {
  const overlay = new ZonesOverlay();
  (series as any).attachPrimitive(overlay);
  return overlay;
}

/**
 * zonesOverlay — lightweight-charts Series Primitive that draws the desk's
 * zone read directly on the price pane:
 *   • supply/demand rectangles extending right from their creation bar
 *   • fib retracement bands (premium red / equilibrium green / discount blue)
 *   • trendline channel rails
 *
 * Everything is drawn in one canvas pass per frame via a bottom-z-order pane
 * view, so it never intercepts crosshair events and costs nothing when the
 * data is empty.
 */
import type {
  ISeriesApi,
  IChartApi,
  SeriesAttachedParameter,
  IUpdatableSeriesPrimitive,
  ISeriesPrimitivePaneView,
  IPrimitivePaneRenderer,
} from 'lightweight-charts';

export interface ZoneRect {
  type: 'supply' | 'demand';
  high: number;
  low: number;
  state: string;
  strength: number;
  createdTime: number; // ms epoch
}

export interface FibBand {
  ratio: number | null;
  price: number | null;
}

export interface FibPayload {
  swing?: { direction?: string | null; high?: number | null; low?: number | null } | null;
  bands: FibBand[];
}

export interface ChannelLine {
  kind: string;
  upperStart: number; // fitted price at window start
  upperNow: number;   // fitted price at last bar
  lowerStart: number;
  lowerNow: number;
  breakout?: string | null;
}

export interface ZonesData {
  supply_zones: ZoneRect[];
  demand_zones: ZoneRect[];
  channels?: ChannelLine[];
  s_r_levels?: { price: number; type: string; touches: number }[];
  fib?: FibPayload;
}

const COLORS = {
  demandFill: 'rgba(34, 197, 94, 0.14)',
  demandEdge: 'rgba(34, 197, 94, 0.55)',
  supplyFill: 'rgba(239, 68, 68, 0.13)',
  supplyEdge: 'rgba(239, 68, 68, 0.5)',
  premium: 'rgba(239, 68, 68, 0.07)',
  equilibrium: 'rgba(34, 197, 94, 0.08)',
  discount: 'rgba(59, 130, 246, 0.09)',
  fibLine: 'rgba(148, 163, 184, 0.45)',
  goldenLine: 'rgba(250, 204, 21, 0.65)',
  channel: 'rgba(96, 165, 250, 0.75)',
};

/** Horizontal band: filled strip between two y values across [x0, x1]. */
interface Band { x0: number; x1: number; yTop: number; yBot: number; fill: string }
/** Straight segment from (x0,y0) → (x1,y1). */
interface Segment { x0: number; x1: number; y0: number; y1: number; stroke: string }

class ZonesPaneRenderer implements IPrimitivePaneRenderer {
  constructor(private bands: Band[], private segments: Segment[]) {}

  draw(target: any) {
    target.useMediaCoordinateSpace((scope: any) => {
      const ctx = scope.context;
      for (const b of this.bands) {
        ctx.fillStyle = b.fill;
        ctx.fillRect(b.x0, Math.min(b.yTop, b.yBot), b.x1 - b.x0, Math.abs(b.yBot - b.yTop));
      }
      for (const s of this.segments) {
        ctx.strokeStyle = s.stroke;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(s.x0, s.y0);
        ctx.lineTo(s.x1, s.y1);
        ctx.stroke();
      }
    });
  }
}

class ZonesPaneView implements ISeriesPrimitivePaneView {
  _bands: Band[] = [];
  _segments: Segment[] = [];
  zOrder(): string { return 'bottom'; }
  renderer(): IPrimitivePaneRenderer {
    return new ZonesPaneRenderer(this._bands, this._segments);
  }
}

export class ZonesOverlay implements IUpdatableSeriesPrimitive {
  private _view = new ZonesPaneView();
  private _data: ZonesData | null = null;
  private _params: SeriesAttachedParameter<any> | null = null;

  setData(data: ZonesData | null) {
    this._data = data;
    this._rebuild();
  }

  attached(params: SeriesAttachedParameter<any>) {
    this._params = params;
  }

  detached() {
    this._params = null;
  }

  updateAllViews() {
    this._rebuild();
  }

  paneViews(): ISeriesPrimitivePaneView[] {
    return [this._view];
  }

  private _rebuild() {
    const bands: Band[] = [];
    const segments: Segment[] = [];
    const p = this._params;
    const data = this._data;
    const hasAny =
      !!data &&
      (!!data.supply_zones?.length ||
        !!data.demand_zones?.length ||
        !!data.channels?.length ||
        !!data.fib?.bands?.length);
    if (!p || !hasAny) {
      this._view._bands = bands;
      this._view._segments = segments;
      return;
    }

    const timeScale = p.chart.timeScale();
    const width = timeScale.width();
    const series = p.series;

    const yOf = (price: number): number | null =>
      series.priceToCoordinate(price) ?? null;

    const xOfMs = (ms: number): number => {
      const x = timeScale.timeToCoordinate(Math.floor(ms / 1000) as any);
      return x ?? -10;
    };

    // ── Supply / Demand rectangles ─────────────────────────────
    for (const z of [...(data.demand_zones ?? []), ...(data.supply_zones ?? [])]) {
      const yTop = yOf(z.high);
      const yBot = yOf(z.low);
      if (yTop === null || yBot === null) continue;
      bands.push({
        x0: Math.max(-10, xOfMs(z.createdTime)),
        x1: width,
        yTop,
        yBot,
        fill: z.type === 'demand' ? COLORS.demandFill : COLORS.supplyFill,
      });
      // Far-edge highlight lines so tested vs fresh reads at a glance.
      const edgeStroke = z.type === 'demand' ? COLORS.demandEdge : COLORS.supplyEdge;
      segments.push({ x0: Math.max(-10, xOfMs(z.createdTime)), x1: width, y0: yTop, y1: yTop, stroke: edgeStroke });
      segments.push({ x0: Math.max(-10, xOfMs(z.createdTime)), x1: width, y0: yBot, y1: yBot, stroke: edgeStroke });
    }

    // ── Fibonacci bands (premium / equilibrium / discount) ─────
    const fib = data.fib;
    if (fib?.bands?.length) {
      const prices = fib.bands
        .filter((b) => b.price != null)
        .map((b) => ({ ratio: b.ratio ?? 0, price: b.price! }))
        .sort((a, b) => b.price - a.price);
      if (prices.length >= 2) {
        const byRatio = (r: number) => prices.find((p) => Math.abs(p.ratio - r) < 1e-6)?.price ?? null;
        const top = prices[0].price;
        const bot = prices[prices.length - 1].price;
        const p382 = byRatio(0.382);
        const p618 = byRatio(0.618);

        if (top !== p382 && p382 !== null) {
          const yT = yOf(top); const yB = yOf(p382);
          if (yT !== null && yB !== null) bands.push({ x0: 0, x1: width, yTop: yT, yBot: yB, fill: COLORS.premium });
        }
        if (p382 !== null && p618 !== null) {
          const yT = yOf(p382); const yB = yOf(p618);
          if (yT !== null && yB !== null) bands.push({ x0: 0, x1: width, yTop: yT, yBot: yB, fill: COLORS.equilibrium });
        }
        if (p618 !== null && bot !== p618) {
          const yT = yOf(p618); const yB = yOf(bot);
          if (yT !== null && yB !== null) bands.push({ x0: 0, x1: width, yTop: yT, yBot: yB, fill: COLORS.discount });
        }

        for (const pr of prices) {
          const y = yOf(pr.price);
          if (y === null) continue;
          const isGolden = pr.ratio >= 0.38 && pr.ratio <= 0.62;
          segments.push({
            x0: 0, x1: width, y0: y, y1: y,
            stroke: isGolden ? COLORS.goldenLine : COLORS.fibLine,
          });
        }
      }
    }

    // ── Channel rails (straight fits across the window) ─────────
    for (const c of data.channels ?? []) {
      for (const pair of [[c.upperStart, c.upperNow], [c.lowerStart, c.lowerNow]] as const) {
        const yA = yOf(pair[0]);
        const yB = yOf(pair[1]);
        if (yA === null || yB === null) continue;
        segments.push({ x0: 0, x1: width, y0: yA, y1: yB, stroke: COLORS.channel });
      }
    }

    this._view._bands = bands;
    this._view._segments = segments;
  }
}

/** Attach the overlay to a candlestick series. */
export function attachZonesOverlay(
  _series: ISeriesApi<'Candlestick'>,
  _chart: IChartApi,
): ZonesOverlay {
  const overlay = new ZonesOverlay();
  (_series as any).attachPrimitive(overlay);
  return overlay;
}

