def _repair_truncated_json(text: str) -> "Optional[Dict[str, Any]]":
    """Close whatever a token ceiling cut and parse the remainder.

    Strategy: track the open string/escape state character by character, then
    append exactly the closers needed (quote, then brackets in reverse order).
    A trailing comma left before the cut is dropped. Returns None when the
    text never opened a JSON object at all.
    """
    stripped = text.lstrip()
    if not stripped.startswith(("{", "[")):
        return None

    stack: list[str] = []
    in_string = False
    escaped = False
    for ch in text:
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
            continue
        if ch == '"':
            in_string = True
        elif ch in "{[":
            stack.append(ch)
        elif ch in "}]":
            if stack:
                stack.pop()

    candidate = text
    # Drop a dangling partial key/value: end after the last complete value.
    if in_string or escaped:
        # Cut back to the opening quote of this unfinished string.
        last_quote = candidate.rfind('"')
        if last_quote != -1:
            candidate = candidate[:last_quote]
    trimmed = candidate.rstrip().rstrip(",")
    if not trimmed.endswith(("{", "[", '"', "}")) :
        # Value was mid-number/word — cut to the previous comma.
        last_comma = trimmed.rfind(",")
        if last_comma > 0:
            trimmed = trimmed[:last_comma]

    closers = []
    for open_ch in reversed(stack):
        closers.append("}" if open_ch == "{" else "]")
    repaired = trimmed + "".join(closers)
    try:
        parsed = json.loads(repaired)
        return parsed if isinstance(parsed, dict) else None
    except json.JSONDecodeError:
        return None

def _repair_truncated_json(text: str) -> "Optional[Dict[str, Any]]":
    """Close whatever a token ceiling cut and parse the remainder.

    Strategy: track the open string/escape state character by character, cut
    back past any dangling partial value, drop trailing commas, then append
    exactly the closers the surviving text needs. Returns None when the text
    never opened a JSON object at all.
    """

    def _scan(s: str) -> "tuple[list[str], bool]":
        """(open-bracket stack for ``s``, whether s ends inside a string)."""
        stack: list[str] = []
        in_string = False
        escaped = False
        for ch in s:
            if in_string:
                if escaped:
                    escaped = False
                elif ch == "\\":
                    escaped = True
                elif ch == '"':
                    in_string = False
                continue
            if ch == '"':
                in_string = True
            elif ch in "{[":
                stack.append(ch)
            elif ch in "}]":
                if stack:
                    stack.pop()
        return stack, in_string

    stripped = text.lstrip()
    if not stripped.startswith(("{", "[")):
        return None

    candidate = text
    stack, in_string = _scan(candidate)

    # Dangling partial string: cut back to its opening quote and rescan.
    if in_string:
        last_quote = candidate.rfind('"')
        if last_quote <= 0:
            return None
        candidate = candidate[:last_quote]
        stack, in_string = _scan(candidate)

    # Drop any trailing comma left before the cut.
    while candidate.rstrip().endswith(","):
        candidate = candidate.rstrip()[:-1]
        stack, _ = _scan(candidate)

    # A value cut mid-number/mid-word (ends in a digit or letter) parses fine
    # as-is once closed; only a bare key ("name":) can't survive — cut it.
    trimmed = candidate.rstrip()
    if trimmed.endswith(":"):
        trimmed = trimmed[:-1].rstrip()
        while trimmed.endswith(","):
            trimmed = trimmed[:-1].rstrip()

    closers = ["}" if o == "{" else "]" for o in reversed(_scan(trimmed)[0])]
    repaired = trimmed + "".join(closers)
    try:
        parsed = json.loads(repaired)
        return parsed if isinstance(parsed, dict) else None
    except json.JSONDecodeError:
        return None

